@namespace sv_ed42ab8b3dff4c5a96eefd2465f2be3f.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>
    <p class="text-muted">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var reference = References[i];
        var idx = i;
        <ReferenceForm Index="idx"
                       Name="@reference.Name"
                       Relationship="@reference.Relationship"
                       Email="@reference.Email"
                       Phone="@reference.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(idx)"
                       OnChanged="HandleReferenceChanged" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (validationError != null)
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationError;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void HandleReferenceChanged((int Index, string Name, string Relationship, string Email, string Phone) data)
    {
        if (data.Index < References.Count)
        {
            References[data.Index] = new ReferenceModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_ed42ab8b3dff4c5a96eefd2465f2be3f.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="mb-3">
        <label class="form-label">Write your cover letter below:</label>
        <textarea class="form-control" rows="12" maxlength="2000"
                  @bind="CoverLetter" @bind:event="oninput"></textarea>
        <div class="form-text text-end">
            @(CoverLetter?.Length ?? 0) / 2000 characters
        </div>
    </div>

    @if (validationError != null)
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationError;

    private async Task HandleNext()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            validationError = "Please write a cover letter before proceeding.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetter);
    }
