                    <small class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mb-1 mt-1">@entry.Description</p>
                    }
                </div>
            }
        </div>
        <hr />

        <div class="review-section">
            <div class="d-flex justify-content-between align-items-center">
                <h5>References</h5>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="mb-2 ms-2">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    <small class="text-muted">@r.Email | @r.Phone</small>
                </div>
            }
        </div>
        <hr />

        <div class="review-section">
            <div class="d-flex justify-content-between align-items-center">
                <h5>Cover Letter</h5>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="ms-2" style="white-space: pre-wrap;">@CoverLetter</p>
        </div>
        <hr />

        @if (submitError != null)
        {
            <div class="alert alert-danger">@submitError</div>
        }

        <div class="step-buttons">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @if (isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = null!;
    [Parameter, EditorRequired] public List<WorkEntry> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private bool isSubmitting;
    private string? submitError;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
"}

