@page "/apply"
@namespace sv_ed42ab8b3dff4c5a96eefd2465f2be3f.Components.Pages.Apply
@using sv_ed42ab8b3dff4c5a96eefd2465f2be3f.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   StepNames="stepNames"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName"
                              Email="@email"
                              Phone="@phone"
                              Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@GetWorkEntries()"
                        References="@GetReferences()"
                        CoverLetter="@coverLetter"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        OnBack="GoBack"
                        OnEditSection="GoToStep"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private bool isSubmitted;
    private int? applicationId;

    private static readonly IReadOnlyList<string> stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new()
    {
        new WorkHistoryStep.WorkEntryModel()
    };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new()
    {
        new ReferencesStep.ReferenceModel(),
        new ReferencesStep.ReferenceModel()
    };

    // Step 4 state
    private string coverLetter = "";

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var application = new JobApplication(
            GetPersonalInfo(),
            new WorkHistory(GetWorkEntries()),
            GetReferences(),
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitted = true;
        completedSteps.Add(4);
    }

    private PersonalInfo GetPersonalInfo() =>
        new(fullName, email, phone, address);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
}

